import { Effect, Layer } from "effect"
import {
  PdfPrinter,
  PrinterUnavailable,
  openPrinter,
  type PdfPrinterService
} from "./PdfPrinter.js"

const fontDirectory = "/var/lib/billing/fonts"

const unavailable = new PrinterUnavailable({
  message: "PDF printing is unavailable. Install the invoice fonts and restart billing."
})

const degradedPrinter: PdfPrinterService = {
  renderInvoice: () => Effect.fail(unavailable),
  listFonts: () => Effect.succeed([])
}

const initializePrinter = openPrinter({ fontDirectory })

export const PdfPrinterLive = Layer.effect(
